"use strict";
class Picture {
  constructor(width, height, pixels) {
    this.width = width;
    this.height = height;
    let sum = 0;
    for (let i = 0; i < pixels.length; i++) sum = (sum * 31 + pixels[i]) >>> 0;
    this.checksum = sum;
    this.preview = Buffer.from(pixels.subarray(0, 24)).toString("base64");
  }
}
exports.Picture = Picture;
exports.decode = (text, width, height, target) => {
  const pixels = Buffer.from(text, "base64");
  if (pixels.length !== width * height) throw new RangeError("not a picture of that size");
  const rows = Math.round((height * target) / width);
  const out = new Uint8Array(target * rows);
  for (let y = 0; y < rows; y++) {
    const from = Math.floor((y * height) / rows) * width;
    for (let x = 0; x < target; x++) out[y * target + x] = pixels[from + Math.floor((x * width) / target)];
  }
  return new Picture(target, rows, out);
};
exports.frame = (index, columns) => "-\\|/"[index % 4].repeat(columns);
